<script setup>import AppShell from'../../Layouts/AppShell.vue';import PageHeader from'../../Components/PageHeader.vue';import UiBadge from'../../Components/UiBadge.vue';import UiButton from'../../Components/UiButton.vue';import UiModal from'../../Components/UiModal.vue';import{Head,router}from'@inertiajs/vue3';import{ref}from'vue';const p=defineProps({event:Object,members:Array,invites:Array}),pending=ref(null),busy=ref(false);function remove(){busy.value=true;router.delete(`/groups/${p.event.id}/members/${pending.value.id}`,{onFinish:()=>{busy.value=false;pending.value=null}})}</script><template><AppShell><Head title="Participants"/><div class="lp-page"><PageHeader eyebrow="Access control" :title="`Participants · ${event.name}`" description="Review membership, role and invitation access."><UiButton variant="secondary" :href="`/groups/${event.id}`">Event workspace</UiButton></PageHeader><div class="mt-8 grid gap-6 xl:grid-cols-[1fr_320px]"><div class="lp-table-wrap"><table class="lp-table"><thead><tr><th>Participant</th><th>Access</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="m in members" :key="m.id"><td><p class="font-semibold">{{m.name}}</p><p class="text-xs text-slate-500">{{m.email}}</p></td><td>{{m.role}} · {{m.access_type}}</td><td><UiBadge :tone="m.status==='active'?'success':'warning'">{{m.status}}</UiBadge></td><td class="text-right"><button v-if="m.role!=='admin'" class="btn-ghost" @click="pending=m">Remove</button></td></tr></tbody></table></div><aside><UiCard><h2 class="text-lg font-bold">Invitation access</h2><div v-for="i in invites" :key="i.id" class="mt-4 border-t border-slate-100 pt-4"><div class="flex justify-between"><p class="font-semibold">{{i.label}}</p><UiBadge :tone="i.active?'success':'error'">{{i.active?'Active':'Unavailable'}}</UiBadge></div><p class="mt-2 font-mono text-sm text-indigo">{{i.code}}</p></div></UiCard></aside></div><UiModal :open="!!pending" title="Remove participant?" :description="`${pending?.name||'This participant'} will lose event access. Existing audit history is retained.`" :busy="busy" @close="pending=null" @confirm="remove"/></div></AppShell></template>
